        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-main);
            color: var(--black);
            line-height: 1.6;
            background-color: var(--white);
            -webkit-font-smoothing: antialiased;
        }

        a { text-decoration: none; color: inherit; }
        ul { list-style: none; }
        img { max-width: 100%; display: block; }

        /* Utilities */
        .container {
            width: 90%;
            max-width: 1200px;
            margin: 0 auto;
            padding: 40px 20px;
        }

        .section-header {
            text-align: center;
            margin-bottom: 60px;
            position: relative;
        }

        .section-header h2 {
            font-size: 24px;
            letter-spacing: 2px;
            text-transform: uppercase;
            font-weight: 600;
            display: inline-block;
            position: relative;
            padding-bottom: 15px;
        }

        .section-header h2::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 60px;
            height: 1px;
            background-color: var(--border-color);
        }

        .btn {
            display: inline-block;
            padding: 12px 30px;
            background: var(--black);
            color: var(--white);
            font-size: 11px;
            letter-spacing: 1.5px;
            text-transform: uppercase;
            border: 1px solid var(--black);
            cursor: pointer;
            transition: all 0.3s ease;
            text-align: center;
        }

        .btn:hover {
            background: transparent;
            color: var(--black);
        }

        .btn-outline {
            background: transparent;
            color: var(--black);
        }
        .btn-outline:hover {
            background: var(--black);
            color: var(--white);
        }

        /* HEADER */
        header {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            z-index: 10;
            padding: 25px 50px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo svg {
            height: 24px;
            fill: white;
        }

        nav ul {
            display: flex;
            gap: 25px;
        }

        nav a {
            color: white;
            font-size: 11px;
            text-transform: uppercase;
            letter-spacing: 1px;
            font-weight: 500;
        }

        /* HERO */
        .hero {
            height: 85vh;
            min-height: 500px;
