            background-size: cover;
            background-position: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            position: relative;
        }

        .hero-overlay {
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(0,0,0,0.35);
        }

        .hero-content {
            position: relative;
            z-index: 2;
            text-align: center;
            color: white;
            border: 2px solid white;
            padding: 40px 80px;
            background: rgba(255,255,255,0.05); /* Subtle transparency hint */
            backdrop-filter: blur(2px);
        }

        .hero-icon {
            width: 120px;
            height: auto;
            margin-bottom: 20px;
            stroke: white;
            stroke-width: 1.5;
            fill: none;
        }

        .hero h1 {
